<template>
    <v-container>
        <template>
            <div class="marks">
                <v-data-table :headers="header" hide-default-footer :items="marks" class=""></v-data-table>
            </div>
            <v-data-table :headers="headers" :sort-by.sync="sortBy" :sort-desc.sync="sortDesc" :items="desserts" class="elevation-1">
              <template v-slot:item.accept="{ item }">
                <v-chip :color="getColor(item.accept)" dark>{{ item.accept }}</v-chip>
              </template>
                <template v-slot:top>
                    <v-toolbar flat color="white">
                        <v-toolbar-title>Сотрудники КЦ</v-toolbar-title>
                        <v-divider class="mx-4" inset vertical></v-divider>
                        <v-spacer></v-spacer>
                        <v-dialog v-model="dialog" max-width="500px">
                            <template v-slot:activator="{ on, attrs }">
                                <v-btn color="primary" dark class="mb-2" v-bind="attrs" v-on="on">Новый оператор</v-btn>
                            </template>
                            <v-card>
                                <v-card-title>
                                    <span class="headline">{{ formTitle }}</span>
                                </v-card-title>

                                <v-card-text>
                                    <v-container>
                                        <v-row>
                                            <v-col cols="12" sm="6" md="4">
                                                <v-text-field v-model="editedItem.mark" label="Оценка"></v-text-field>
                                            </v-col>
                                            <v-col cols="12" sm="6" md="4">
                                                <v-text-field v-model="editedItem.id" label="ID"></v-text-field>
                                            </v-col>
                                            <v-col cols="12" sm="6" md="4">
                                                <v-text-field v-model="editedItem.name" label="Имя"></v-text-field>
                                            </v-col>
                                            <v-col cols="12" sm="6" md="4">
                                                <v-text-field v-model="editedItem.calls" label="К-во звонков"></v-text-field>
                                            </v-col>
                                            <v-col cols="12" sm="6" md="4">
                                                <v-text-field v-model="editedItem.orders" label="Выполненные заказы"></v-text-field>
                                            </v-col>
                                        </v-row>
                                    </v-container>
                                </v-card-text>

                                <v-card-actions>
                                    <v-spacer></v-spacer>
                                    <v-btn color="blue darken-1" text @click="close">Отменить</v-btn>
                                    <v-btn color="blue darken-1" text @click="save">Сохранить</v-btn>
                                </v-card-actions>
                            </v-card>
                        </v-dialog>
                    </v-toolbar>
                </template>
                <template v-slot:item.actions="{ item }">
                    <v-icon
                            small
                            class="mr-2"
                            @click="editItem(item)"
                    >
                        mdi-pencil
                    </v-icon>
                    <v-icon
                            small
                            @click="deleteItem(item)"
                    >
                        mdi-delete
                    </v-icon>
                </template>
                <template v-slot:no-data>
                    <v-btn color="primary" @click="initialize">Reset</v-btn>
                </template>
            </v-data-table>
        </template>
    </v-container>
</template>
<script>
    export default {
        data: () => ({
            dialog: false,
            sortBy: 'accept',
            sortDesc: true,
            header:[
                {
                    text: 'Оценка',
                    align: 'start',
                    sortable: false,
                    value: 'mark',
                }
            ],

            headers: [
                {
                    text: 'Оценка',
                    align: 'start',
                    sortable: false,
                    value: 'mark',
                },
                {text: 'ID', value: 'id', sortable: false},
                {text: 'Имя', value: 'name', sortable: false},
                {text: 'К-во звонков', value: 'calls', sortable: false},
                {text: 'Выполненные заказы', value: 'orders', sortable: false},
                {text: 'Отказ', value: 'decline', sortable: false},
                {text: 'Апрув (%)', value: 'accept', sortable: false},
                {text: 'Действия', value: 'actions', sortable: false},
            ],
            desserts: [],
            editedIndex: -1,
            editedItem: {
                mark: '',
                id: 0,
                name: '',
                calls: 0,
                orders: 0,
                decline: 0,
                accept: 0,
                actions: 0,
            },
            defaultItem: {
                mark: '',
                id: 0,
                name: '',
                calls: 0,
                orders: 0,
                decline: 0,
                accept: 0,
                actions: 0,
            },
        }),

        computed: {
            formTitle() {
                return this.editedIndex === -1 ? 'Новый оператор' : 'Редактировать оператора'
            },
        },

        watch: {
            dialog(val) {
                val || this.close()
            },
        },

        created() {
            this.initialize();
            this.getDeclines();
            this.getAccept();
        },

        methods: {
            initialize() {
                this.marks = [
                    {
                        mark: 100,
                    },
                    {
                        mark: 90,
                    },
                    {
                        mark: 80,
                    },
                    {
                        mark: 70,
                    },
                    {
                        mark: 60,
                    },
                    {
                        mark: 50,
                    },
                    {
                        mark: 40,
                    },
                    {
                        mark: 30,
                    },
                    {
                        mark: 20,
                    },
                    {
                        mark: 10,
                    },
                ]
                this.desserts = [
                    {
                      mark: 100,
                      id: 1,
                      name: 'Оксана',
                      calls: 125,
                      orders: 98,
                      decline: 0,
                      accept: 0,
                      actions: 0,
                    },
                    {
                      mark: 90,
                      id: 2,
                      name: 'Лена',
                      calls: 118,
                      orders: 79,
                      decline: 0,
                      accept: 0,
                      actions: 0,
                    },
                    {
                      mark: 80,
                      id: 3,
                      name: 'Света',
                      calls: 145,
                      orders: 110,
                      decline: 0,
                      accept: 0,
                      actions: 0,
                    },
                    {
                      mark: 70,
                      id: 4,
                      name: 'Катя',
                      calls: 105,
                      orders: 100,
                      decline: 0,
                      accept: 0,
                      actions: 0,
                    },
                    {
                      mark: 60,
                      id: 5,
                      name: 'Оля',
                      calls: 89,
                      orders: 80,
                      decline: 0,
                      accept: 0,
                      actions: 0,
                    },
                    {
                      mark: 50,
                      id: 6,
                      name: 'Ира',
                      calls: 97,
                      orders: 96,
                      decline: 0,
                      accept: 0,
                      actions: 0,
                    },
                    {
                      mark: 40,
                      id: 7,
                      name: 'Альона',
                      calls: 133,
                      orders: 120,
                      decline: 0,
                      accept: 0,
                      actions: 0,
                    },
                    {
                      mark: 30,
                      id: 8,
                      name: 'Оля',
                      calls: 111,
                      orders: 92,
                      decline: 0,
                      accept: 0,
                      actions: 0,
                    },
                    {
                      mark: 20,
                      id: 9,
                      name: 'Вика',
                      calls: 120,
                      orders: 105,
                      decline: 0,
                      accept: 0,
                      actions: 0,
                    },
                    {
                      mark: 10,
                      id: 10,
                      name: 'Люда',
                      calls: 99,
                      orders: 70,
                      decline: 0,
                      accept: 0,
                      actions: 0,
                    },
                ]
            },

            editItem(item) {
                this.editedIndex = this.desserts.indexOf(item)
                this.editedItem = Object.assign({}, item)
                this.dialog = true
            },

            deleteItem(item) {
                const index = this.desserts.indexOf(item)
                confirm('Вы действительно хотите удалить этого оператора?') && this.desserts.splice(index, 1)
            },

            close() {
                this.dialog = false
                this.$nextTick(() => {
                    this.editedItem = Object.assign({}, this.defaultItem)
                    this.editedIndex = -1
                })
            },

            save() {
                if (this.editedIndex > -1) {
                    Object.assign(this.desserts[this.editedIndex], this.editedItem)
                } else {
                    this.desserts.push(this.editedItem)
                }
                this.getDeclines();
                this.getAccept();
                this.close();
            },

            getColor (accept) {
              if (accept < 40) return 'red'
              else if (accept > 40 && accept < 80) return 'orange'
              else return 'green'
            },

            getDeclines () {
              this.desserts.map((data)=> {
                data.decline = data.calls - data.orders;
              });
            },

          getAccept () {
            this.desserts.map((data)=> {
              data.accept = parseInt(data.orders/data.calls*100);
            });
          },
        },
    }
</script>
<style>
    body {
        min-width: 1024px;
    }
    .container {
        position: relative;
    }
    .marks {
        width: 75px;
        position: absolute;
        left: 12px;
        bottom: 71px;
    }
</style>